<?php
require_once __DIR__.'/../includes/bootstrap.php';if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$email=trim($_POST['email']);$token=trim($_POST['token']);$new=$_POST['password'];$q=db()->prepare('SELECT pr.*,u.email FROM password_resets pr JOIN users u ON u.id=pr.user_id WHERE u.email=? AND pr.used_at IS NULL AND pr.expires_at>NOW() ORDER BY pr.id DESC LIMIT 1');$q->execute([$email]);$r=$q->fetch();if($r&&password_verify($token,$r['token_hash'])){db()->prepare('UPDATE users SET password_hash=? WHERE id=?')->execute([password_hash($new,PASSWORD_DEFAULT),$r['user_id']]);db()->prepare('UPDATE password_resets SET used_at=NOW() WHERE id=?')->execute([$r['id']]);redirect('login.php');}$err='Invalid or expired token';}?><!doctype html><html><body style='font-family:Arial;max-width:520px;margin:60px auto'><h2>Set New Password</h2><?php if(!empty($err))echo '<div>'.e($err).'</div>';?><form method='post'><input type='hidden' name='csrf' value='<?=e(csrf_token())?>'><input name='email' placeholder='Email' required><input name='token' placeholder='Token' required><input name='password' type='password' placeholder='New password' required><button>Reset</button></form></body></html>